# Schema Migration Planner demo: diff -> classify -> expand/contract plan.
OLD={"id":"int","name":"str","age":"int"}
NEW={"id":"int","full_name":"str","age":"str","email":"str"}
def diff(old,new):
    plan=[]
    for f in new:
        if f not in old: plan.append(("add",f,"backward-compatible"))
    for f in old:
        if f not in new: plan.append(("remove?",f,"check rename first"))
    for f in set(old)&set(new):
        if old[f]!=new[f]: plan.append(("retype %s %s->%s"%(f,old[f],new[f]),f,"breaking?"))
    return plan
for step in diff(OLD,NEW): print(step)
print("plan: 1.expand(add full_name,email) 2.dual-write 3.backfill 4.contract(remove name)")

